<?php defined('ABSPATH') || exit; ?>
<section class="how-section" aria-labelledby="how-title"><div class="how-content"><h2 id="how-title"><?php echo nl2br(esc_html(gamilea_field('title', 'Comprar aquí es así de fácil'))); ?></h2><div class="steps"><?php $step_icons = array('imgStepIcon.svg','imgStepIcon1.svg','imgStepIcon2.svg'); foreach (array_values(get_field('items') ?: gamilea_default_steps()) as $i => $item) : if (!is_array($item)) { continue; } $icon = !empty($item['image']) ? $item['image'] : gamilea_asset($step_icons[$i % 3]); ?><div class="step"><span class="step-icon"><img src="<?php echo esc_url($icon); ?>" alt=""></span><div><h3><?php echo esc_html($item['title'] ?? ''); ?></h3><p><?php echo nl2br(esc_html($item['description'] ?? '')); ?></p></div></div><?php endforeach; ?></div></div><?php $image = get_field('image'); if ($image) : ?><img class="delivery-photo gamilea-custom-delivery" src="<?php echo esc_url($image); ?>" alt=""><?php else : echo gamilea_crop('delivery-photo','Buenas cosas llegan a tu casa'); endif; ?></section>
